insert into public.shop_templates
  (slug, title, summary, description, category, tech_stack, price, demo_url, thumbnail_url, screenshots, mobile_screenshots, features, version, file_size, storage_file_path, status)
values
('website-analytics-dark-dashboard', 'Website Analytics Dark Dashboard', 'Dashboard analitik website bermode gelap: pengunjung, funnel konversi, halaman teratas, dan sumber trafik.', 'Dashboard analitik dengan mode gelap sebagai bawaan dan navigasi di atas tanpa sidebar. Berisi kartu KPI, grafik pengunjung dengan tooltip, funnel konversi empat tahap, tabel halaman teratas, dan sumber trafik. Rentang data bisa diganti 7 hari, 30 hari, atau 12 bulan, dan tema bisa diganti ke terang.', 'Dashboard', array['HTML', 'Tailwind'], 0, null, '/templates/free-analytics-dark/card.webp', array['/templates/free-analytics-dark/desktop-1.webp'], array['/templates/free-analytics-dark/mobile-1.webp'], array['Mode gelap bawaan, bisa diganti terang', 'Grafik garis SVG dengan tooltip, tanpa library', 'Rentang data 7 hari / 30 hari / 12 bulan', 'Funnel konversi dan tabel halaman teratas', 'Navigasi di atas tanpa sidebar'], 'v1.0.0', null, 'free-analytics-dark/free-analytics-dark-v1.0.0.zip', 'Terbit'),
('mobile-app-landing-page', 'Mobile App Landing Page', 'Landing page aplikasi HP dengan mockup ponsel dari CSS, fitur, cara kerja, ulasan, dan tombol unduh.', 'Landing page satu halaman untuk memperkenalkan aplikasi mobile. Mockup ponsel dibuat langsung dari HTML dan CSS, lalu dilengkapi tiga fitur utama, cara kerja tiga langkah, slider ulasan pengguna, dan tombol unduh toko aplikasi.', 'Landing Page', array['HTML', 'Tailwind'], 0, null, '/templates/free-app-landing/card.webp', array['/templates/free-app-landing/desktop-1.webp', '/templates/free-app-landing/desktop-2.webp', '/templates/free-app-landing/desktop-3.webp'], array['/templates/free-app-landing/mobile-1.webp'], array['Mockup ponsel dari HTML/CSS, mudah diganti', 'Slider ulasan pengguna', 'Cara kerja tiga langkah', 'Menu HP siap pakai', 'Cukup buka index.html'], 'v1.0.0', null, 'free-app-landing/free-app-landing-v1.0.0.zip', 'Terbit'),
('teras-kopi-cafe-landing', 'Teras Kopi Café Landing', 'Landing page kafe dan bakery yang hangat: menu per kategori, jam buka, cerita kafe, dan lokasi.', 'Template untuk kedai kopi, kafe, atau bakery. Menampilkan status buka atau tutup otomatis sesuai jam, menu dengan tab Coffee, Non-coffee, dan Pastry, cerita singkat kafe, galeri suasana dari ilustrasi, serta jam buka dan lokasi.', 'Landing Page', array['HTML', 'Tailwind'], 0, null, '/templates/free-cafe-landing/card.webp', array['/templates/free-cafe-landing/desktop-1.webp', '/templates/free-cafe-landing/desktop-2.webp', '/templates/free-cafe-landing/desktop-3.webp'], array['/templates/free-cafe-landing/mobile-1.webp'], array['Status Open now / Closed otomatis sesuai jam', 'Menu dengan tab kategori', 'Tabel jam buka 7 hari', 'Galeri suasana dari ilustrasi HTML/CSS', 'Menu HP siap pakai'], 'v1.0.0', null, 'free-cafe-landing/free-cafe-landing-v1.0.0.zip', 'Terbit'),
('dental-clinic-landing-page', 'Dental Clinic Landing Page', 'Landing page klinik gigi: layanan, dokter, jam praktik, dan form janji temu dengan validasi.', 'Template bersih untuk klinik gigi atau praktik kesehatan kecil. Berisi enam layanan, profil tiga dokter, jadwal praktik, dan form janji temu yang memeriksa isian lalu menampilkan konfirmasi.', 'Landing Page', array['HTML', 'Tailwind'], 0, null, '/templates/free-clinic-landing/card.webp', array['/templates/free-clinic-landing/desktop-1.webp', '/templates/free-clinic-landing/desktop-2.webp'], array['/templates/free-clinic-landing/mobile-1.webp'], array['Form janji temu dengan validasi dan konfirmasi', 'Enam kartu layanan', 'Profil dokter dan jadwal praktik', 'Menu HP siap pakai', 'Cukup buka index.html'], 'v1.0.0', null, 'free-clinic-landing/free-clinic-landing-v1.0.0.zip', 'Terbit'),
('alder-group-company-profile', 'Alder Group Company Profile', 'Company profile editorial untuk perusahaan konstruksi atau konsultan: layanan, proyek, tim, dan kantor cabang.', 'Template company profile dengan gaya editorial: ringkasan perusahaan dan angka pencapaian, tiga prinsip kerja, empat layanan utama, daftar proyek dengan filter sektor, tim pimpinan, kantor regional, dan form pertanyaan.', 'Landing Page', array['HTML', 'Tailwind'], 0, null, '/templates/free-company/card.webp', array['/templates/free-company/desktop-1.webp', '/templates/free-company/desktop-2.webp', '/templates/free-company/desktop-3.webp'], array['/templates/free-company/mobile-1.webp'], array['8 bagian: hero, tentang, layanan, proyek, tim, kantor, kontak, footer', 'Filter proyek per sektor', 'Menu HP siap pakai', 'Tanpa framework, cukup buka index.html'], 'v1.0.0', null, 'free-company/free-company-v1.0.0.zip', 'Terbit'),
('social-content-planner-dashboard', 'Social Content Planner Dashboard', 'Dashboard perencanaan konten sosial media: tab Ideas, Scheduled, Published dengan grid kartu konten.', 'Dashboard untuk tim konten. Sidebar putih dengan grup menu yang bisa dilipat, tab berangka (Ideas, Scheduled, Published), grid kartu konten per platform, pencarian, popup tambah konten, export CSV, dan mode gelap.', 'Dashboard', array['HTML', 'Tailwind'], 0, null, '/templates/free-content-planner/card.webp', array['/templates/free-content-planner/desktop-1.webp'], array['/templates/free-content-planner/mobile-1.webp'], array['Tab berangka dan grid kartu 4 kolom', 'Popup tambah konten baru', 'Pencarian dan export CSV', 'Mode gelap tersimpan di browser', 'Sidebar dengan grup menu lipat'], 'v1.0.0', null, 'free-content-planner/free-content-planner-v1.0.0.zip', 'Terbit'),
('forge-coding-bootcamp-landing', 'Forge Coding Bootcamp Landing', 'Landing page kursus online atau bootcamp: hitung mundur pendaftaran, kurikulum, mentor, dan form daftar.', 'Template untuk kursus online, bootcamp, atau kelas pelatihan. Berisi jadwal angkatan dengan hitung mundur pendaftaran, profil peserta, kurikulum 12 minggu yang bisa dibuka per minggu, mentor, testimoni alumni, dan form pendaftaran dengan validasi.', 'Landing Page', array['HTML', 'Tailwind'], 0, null, '/templates/free-course-landing/card.webp', array['/templates/free-course-landing/desktop-1.webp', '/templates/free-course-landing/desktop-2.webp', '/templates/free-course-landing/desktop-3.webp'], array['/templates/free-course-landing/mobile-1.webp'], array['Hitung mundur pendaftaran', 'Kurikulum mingguan model accordion', 'Form pendaftaran dengan validasi', 'Profil mentor dan testimoni alumni', 'Menu HP siap pakai'], 'v1.0.0', null, 'free-course-landing/free-course-landing-v1.0.0.zip', 'Terbit'),
('pipeline-crm-dashboard', 'Pipeline CRM Dashboard', 'Dashboard CRM penjualan dengan papan kanban deal yang bisa dipindah dan tabel kontak yang bisa dicari.', 'Dashboard CRM sederhana untuk tim sales. Empat kartu angka pipeline, papan kanban empat tahap (Lead, Qualified, Proposal, Won) yang kartunya bisa dipindah, dan tabel kontak terbaru dengan pencarian.', 'Dashboard', array['HTML', 'Tailwind'], 0, null, '/templates/free-crm-dashboard/card.webp', array['/templates/free-crm-dashboard/desktop-1.webp'], array['/templates/free-crm-dashboard/mobile-1.webp'], array['Kanban deal dengan drag & drop', 'Kartu KPI pipeline', 'Tabel kontak dengan pencarian', 'Sidebar jadi menu geser di HP'], 'v1.0.0', null, 'free-crm-dashboard/free-crm-dashboard-v1.0.0.zip', 'Terbit'),
('harbor-sales-dashboard', 'Harbor Sales Dashboard', 'Dashboard penjualan toko online dengan mode gelap, grafik, dan tabel pesanan. Gratis, cukup HTML dan Tailwind CSS.', 'Dashboard admin untuk toko online: kartu KPI, grafik penjualan 7 hari sampai 12 bulan, sumber pengunjung, pesanan terbaru dengan filter dan pencarian, serta produk terlaris. Ada mode gelap dan menu geser di HP. Grafiknya dibuat tanpa library tambahan.', 'Dashboard', array['HTML', 'Tailwind'], 0, null, '/templates/free-dashboard/card.webp', array['/templates/free-dashboard/desktop-1.webp', '/templates/free-dashboard/desktop-2.webp', '/templates/free-dashboard/desktop-3.webp'], array['/templates/free-dashboard/mobile-1.webp', '/templates/free-dashboard/mobile-2.webp'], array['Mode gelap yang diingat browser', 'Grafik penjualan 7 hari / 30 hari / 12 bulan tanpa library', 'Tabel pesanan dengan filter status dan pencarian', 'Kartu KPI, sumber pengunjung, dan produk terlaris', 'Sidebar jadi menu geser di HP'], 'v1.0.0', null, 'free-dashboard/free-dashboard-v1.0.0.zip', 'Terbit'),
('workshop-and-event-landing-page', 'Workshop & Event Landing Page', 'Landing page workshop atau acara: hitung mundur, jadwal per hari, pembicara, tiket, dan FAQ.', 'Template satu halaman untuk workshop, seminar, atau konferensi kecil. Hitung mundur ke hari acara, jadwal sesi dengan tab Day 1 dan Day 2, kartu pembicara, dua jenis tiket, info lokasi, dan FAQ.', 'Landing Page', array['HTML', 'Tailwind'], 0, null, '/templates/free-event-landing/card.webp', array['/templates/free-event-landing/desktop-1.webp', '/templates/free-event-landing/desktop-2.webp', '/templates/free-event-landing/desktop-3.webp'], array['/templates/free-event-landing/mobile-1.webp'], array['Hitung mundur ke hari acara', 'Jadwal dengan tab per hari', 'Dua pilihan tiket', 'FAQ model accordion', 'Menu HP siap pakai'], 'v1.0.0', null, 'free-event-landing/free-event-landing-v1.0.0.zip', 'Terbit'),
('minimal-fashion-store', 'Minimal Fashion Store', 'Toko fashion minimalis dengan filter kategori, quick view produk, pilihan ukuran, dan keranjang belanja.', 'Template toko pakaian bergaya minimalis. Hero koleksi, grid delapan produk dengan filter kategori, popup quick view dengan pilihan ukuran S sampai XL, dan keranjang geser dari samping yang tersimpan di browser.', 'E-Commerce', array['HTML', 'Tailwind'], 0, null, '/templates/free-fashion-store/card.webp', array['/templates/free-fashion-store/desktop-1.webp', '/templates/free-fashion-store/desktop-2.webp'], array['/templates/free-fashion-store/mobile-1.webp'], array['Quick view produk dengan pilihan ukuran', 'Keranjang geser tersimpan di browser', 'Filter kategori produk', 'Menu HP siap pakai'], 'v1.0.0', null, 'free-fashion-store/free-fashion-store-v1.0.0.zip', 'Terbit'),
('personal-finance-dashboard', 'Personal Finance Dashboard', 'Dashboard keuangan pribadi: saldo, grafik pengeluaran, kategori, transaksi, dan target tabungan.', 'Dashboard untuk mencatat keuangan pribadi. Kartu saldo, pemasukan, dan pengeluaran bulan ini, grafik pengeluaran mingguan, donut pengeluaran per kategori, daftar transaksi dengan filter, form tambah transaksi, dan target tabungan.', 'Dashboard', array['HTML', 'Tailwind'], 0, null, '/templates/free-finance-dashboard/card.webp', array['/templates/free-finance-dashboard/desktop-1.webp'], array['/templates/free-finance-dashboard/mobile-1.webp'], array['Tambah transaksi tersimpan di browser', 'Grafik batang dan donut tanpa library', 'Filter transaksi masuk / keluar', 'Progress target tabungan', 'Menu HP siap pakai'], 'v1.0.0', null, 'free-finance-dashboard/free-finance-dashboard-v1.0.0.zip', 'Terbit'),
('food-order-page', 'Food Order Page', 'Halaman pesan makanan untuk warung, kafe, atau katering: pilih menu, hitung total, kirim pesanan lewat WhatsApp.', 'Template satu halaman untuk usaha makanan yang menerima pesanan lewat chat. Menu per kategori dengan pencarian, tombol tambah dan kurang jumlah, ringkasan pesanan dengan total otomatis, dan tombol kirim pesanan lewat WhatsApp.', 'E-Commerce', array['HTML', 'Tailwind'], 0, null, '/templates/free-food-order/card.webp', array['/templates/free-food-order/desktop-1.webp', '/templates/free-food-order/desktop-2.webp'], array['/templates/free-food-order/mobile-1.webp'], array['Kirim pesanan lewat WhatsApp', 'Total pesanan otomatis', 'Menu per kategori dengan pencarian', 'Ringkasan pesanan menempel di layar', 'Menu HP siap pakai'], 'v1.0.0', null, 'free-food-order/free-food-order-v1.0.0.zip', 'Terbit'),
('hr-recruitment-dashboard', 'HR Recruitment Dashboard', 'Dashboard HR dan rekrutmen: kartu sambutan, progres kandidat, kalender wawancara, dan profil HR.', 'Dashboard rekrutmen dengan sidebar berwarna solid. Kartu sambutan berisi ringkasan lamaran, daftar kandidat sebagai kartu terpisah dengan menu tahap, kalender bulan yang bisa diganti dan dipilih rentang tanggalnya, serta kartu profil HR manager.', 'Dashboard', array['HTML', 'Tailwind'], 0, null, '/templates/free-hr-dashboard/card.webp', array['/templates/free-hr-dashboard/desktop-1.webp'], array['/templates/free-hr-dashboard/mobile-1.webp'], array['Kalender interaktif dengan rentang tanggal', 'Menu tahap kandidat per baris', 'Sidebar berwarna dengan menu geser di HP', 'Kartu profil dengan tombol kontak'], 'v1.0.0', null, 'free-hr-dashboard/free-hr-dashboard-v1.0.0.zip', 'Terbit'),
('inventory-dashboard', 'Inventory Dashboard', 'Dashboard stok gudang atau toko: tabel produk yang bisa diurutkan, filter kategori, dan peringatan stok menipis.', 'Dashboard manajemen stok dengan sidebar yang bisa diciutkan. Kartu ringkas SKU dan nilai stok, tabel produk padat yang bisa diurutkan per kolom dengan bar level stok, chip filter kategori, pencarian, dan panel stok menipis dengan tombol restock.', 'Dashboard', array['HTML', 'Tailwind'], 0, null, '/templates/free-inventory-dashboard/card.webp', array['/templates/free-inventory-dashboard/desktop-1.webp'], array['/templates/free-inventory-dashboard/mobile-1.webp'], array['Tabel produk bisa diurutkan per kolom', 'Filter kategori dan pencarian', 'Panel stok menipis dengan restock', 'Sidebar bisa diciutkan jadi ikon'], 'v1.0.0', null, 'free-inventory-dashboard/free-inventory-dashboard-v1.0.0.zip', 'Terbit'),
('nara-portfolio-landing-page', 'Nara Portfolio Landing Page', 'Landing page portofolio satu halaman untuk web developer dan desainer. Gratis, cukup HTML dan Tailwind CSS.', 'Halaman portofolio yang bersih dan apa adanya: perkenalan dengan foto, layanan, tentang saya, karya, keahlian, ajakan kerja sama, dan kontak. Gayanya polos dengan bingkai garis dan tipografi tegas, jadi karyamu yang menonjol.', 'Portfolio', array['HTML', 'Tailwind'], 0, null, '/templates/free-landing/card.webp', array['/templates/free-landing/desktop-1.webp', '/templates/free-landing/desktop-2.webp', '/templates/free-landing/desktop-3.webp'], array['/templates/free-landing/mobile-1.webp'], array['8 bagian: hero, layanan, tentang saya, karya, keahlian, ajakan, kontak', 'Slider keahlian dengan tombol panah dan geser di HP', 'Menu HP siap pakai', 'Tanpa framework, cukup buka index.html'], 'v1.0.0', null, 'free-landing/free-landing-v1.0.0.zip', 'Terbit'),
('student-learning-dashboard', 'Student Learning Dashboard', 'Dashboard siswa kursus online: streak belajar, progres kursus, jadwal mingguan, dan tugas.', 'Dashboard untuk siswa platform belajar online dengan sidebar mengambang. Sapaan dan streak belajar harian, tiga kartu progres kursus, timeline jadwal Senin sampai Jumat, dan daftar tugas yang bisa dicentang.', 'Dashboard', array['HTML', 'Tailwind'], 0, null, '/templates/free-learning-dashboard/card.webp', array['/templates/free-learning-dashboard/desktop-1.webp'], array['/templates/free-learning-dashboard/mobile-1.webp'], array['Timeline jadwal dengan tab per hari', 'Tugas bisa dicentang, tersimpan di browser', 'Kartu progres kursus', 'Sidebar mengambang dengan menu geser di HP'], 'v1.0.0', null, 'free-learning-dashboard/free-learning-dashboard-v1.0.0.zip', 'Terbit'),
('single-product-page', 'Single Product Page', 'Halaman satu produk: galeri empat sudut, pilihan warna, jumlah, tab informasi, ulasan, dan produk terkait.', 'Template halaman produk tunggal untuk toko online. Galeri empat sudut pandang, pilihan warna yang langsung mengubah warna gambar produk, pilihan jumlah, tombol tambah ke keranjang dengan notifikasi, tab deskripsi, spesifikasi, dan pengiriman, ulasan pembeli, serta produk terkait.', 'E-Commerce', array['HTML', 'Tailwind'], 0, null, '/templates/free-product-page/card.webp', array['/templates/free-product-page/desktop-1.webp', '/templates/free-product-page/desktop-2.webp'], array['/templates/free-product-page/mobile-1.webp'], array['Pilihan warna mengubah gambar produk', 'Galeri dengan thumbnail', 'Tab deskripsi, spesifikasi, pengiriman', 'Notifikasi tambah ke keranjang', 'Menu HP siap pakai'], 'v1.0.0', null, 'free-product-page/free-product-page-v1.0.0.zip', 'Terbit'),
('team-project-dashboard', 'Team Project Dashboard', 'Dashboard proyek tim: progres proyek, tugas hari ini, kalender mingguan, dan anggota tim.', 'Dashboard manajemen proyek sederhana. Daftar proyek dengan tab Active dan Completed, progress bar dan tenggat, tugas hari ini yang bisa dicentang, kalender mini minggu ini, dan daftar anggota tim dengan jumlah tugasnya.', 'Dashboard', array['HTML', 'Tailwind'], 0, null, '/templates/free-project-dashboard/card.webp', array['/templates/free-project-dashboard/desktop-1.webp'], array['/templates/free-project-dashboard/mobile-1.webp'], array['Tugas bisa dicentang, tersimpan di browser', 'Tab proyek aktif dan selesai', 'Kalender mingguan', 'Menu HP siap pakai'], 'v1.0.0', null, 'free-project-dashboard/free-project-dashboard-v1.0.0.zip', 'Terbit'),
('one-page-online-resume', 'One-page Online Resume', 'CV online satu halaman bergaya dokumen yang rapi dan bisa langsung disimpan sebagai PDF.', 'Template CV satu halaman untuk pencari kerja. Berisi kontak dan tautan, ringkasan, timeline pengalaman kerja, pendidikan, keahlian per kelompok, proyek pilihan, bahasa, dan sertifikat. Tombol Download PDF mencetak halaman dengan tata letak A4 yang rapi.', 'Portfolio', array['HTML', 'Tailwind'], 0, null, '/templates/free-resume/card.webp', array['/templates/free-resume/desktop-1.webp', '/templates/free-resume/desktop-2.webp'], array['/templates/free-resume/mobile-1.webp'], array['Tombol Download PDF dengan tata letak A4', 'Timeline pengalaman kerja', 'Keahlian dikelompokkan tanpa bar persentase', 'Cukup buka index.html'], 'v1.0.0', null, 'free-resume/free-resume-v1.0.0.zip', 'Terbit'),
('lumen-analytics-saas-landing', 'Lumen Analytics SaaS Landing', 'Landing page produk SaaS: mockup dashboard dari HTML, fitur, integrasi, harga bulanan/tahunan, dan FAQ.', 'Landing page yang tenang untuk produk SaaS. Hero dengan mockup dashboard dari HTML dan CSS, deretan logo pelanggan, tiga fitur utama dengan ilustrasi kecil, grid integrasi, tabel harga dengan pilihan bulanan atau tahunan, FAQ, dan form coba gratis.', 'SaaS', array['HTML', 'Tailwind'], 0, null, '/templates/free-saas-landing/card.webp', array['/templates/free-saas-landing/desktop-1.webp', '/templates/free-saas-landing/desktop-2.webp', '/templates/free-saas-landing/desktop-3.webp'], array['/templates/free-saas-landing/mobile-1.webp'], array['Harga dengan toggle bulanan / tahunan', 'Mockup dashboard dari HTML/CSS', 'FAQ model accordion', 'Menu HP siap pakai', 'Cukup buka index.html'], 'v1.0.0', null, 'free-saas-landing/free-saas-landing-v1.0.0.zip', 'Terbit'),
('kova-modern-storefront', 'Kova Modern Storefront', 'Toko online minimalis dengan katalog produk, pencarian, filter kategori, dan keranjang belanja geser.', 'Template toko online yang tenang dan minimalis: koleksi unggulan, keunggulan toko, katalog produk dengan filter kategori dan pencarian, bagian tentang toko, form newsletter, serta keranjang belanja yang muncul dari samping lengkap dengan target gratis ongkir.', 'E-Commerce', array['HTML', 'Tailwind'], 0, null, '/templates/free-store/card.webp', array['/templates/free-store/desktop-1.webp', '/templates/free-store/desktop-2.webp', '/templates/free-store/desktop-3.webp'], array['/templates/free-store/mobile-1.webp'], array['Katalog produk dengan filter kategori dan pencarian', 'Keranjang belanja geser dengan pengaturan jumlah', 'Penanda target gratis ongkir', 'Menu HP siap pakai'], 'v1.0.0', null, 'free-store/free-store-v1.0.0.zip', 'Terbit'),
('support-desk-dashboard', 'Support Desk Dashboard', 'Dashboard helpdesk tiga kolom: antrean tiket, percakapan, dan detail pelanggan.', 'Dashboard layanan pelanggan dengan rail ikon sempit. Kolom antrean tiket dengan filter status dan prioritas, kolom percakapan dengan kotak balasan, dan kolom detail pelanggan beserta riwayat tiket. Di HP tampil satu kolom dengan tombol kembali.', 'Dashboard', array['HTML', 'Tailwind'], 0, null, '/templates/free-support-desk/card.webp', array['/templates/free-support-desk/desktop-1.webp'], array['/templates/free-support-desk/mobile-1.webp'], array['Klik tiket mengganti percakapan dan detail', 'Kirim balasan langsung tampil', 'Filter status tiket', 'Tampilan satu kolom di HP'], 'v1.0.0', null, 'free-support-desk/free-support-desk-v1.0.0.zip', 'Terbit')
